'use client';

import { useEffect, useState, type CSSProperties } from 'react';
import './toast-stack.css';

export interface Toast {
  id: number;
  message: string;
}

export interface ToastStackProps {
  toasts: Toast[];
  /** Called once a toast has finished leaving. Remove it from your list. */
  onDismiss: (id: number) => void;
  /** Time before a toast leaves on its own, in milliseconds. */
  duration?: number;
  /** How many toasts stay visible in the stack. */
  max?: number;
  /**
   * By default the stack is pinned to the viewport. Set this to pin it inside
   * the nearest ancestor with `position: relative`.
   */
  contained?: boolean;
  className?: string;
}

function ToastItem({
  toast,
  depth,
  duration,
  onDismiss,
}: {
  toast: Toast;
  depth: number;
  duration: number;
  onDismiss: (id: number) => void;
}) {
  const [leaving, setLeaving] = useState(false);

  useEffect(() => {
    const timer = window.setTimeout(() => setLeaving(true), duration);
    return () => window.clearTimeout(timer);
  }, [duration]);

  return (
    <li
      className='mg-toasts__slot'
      style={{ '--mg-depth': depth } as CSSProperties}
    >
      <div
        className='mg-toasts__toast'
        data-leaving={leaving}
        role='status'
        onAnimationEnd={() => leaving && onDismiss(toast.id)}
      >
        <span>{toast.message}</span>
        <button
          type='button'
          className='mg-toasts__close'
          aria-label={`Dismiss: ${toast.message}`}
          onClick={() => setLeaving(true)}
        >
          <svg width='16' height='16' viewBox='0 0 16 16' aria-hidden='true'>
            <path
              d='M4 4l8 8M12 4l-8 8'
              fill='none'
              stroke='currentColor'
              strokeWidth='1.75'
              strokeLinecap='round'
            />
          </svg>
        </button>
      </div>
    </li>
  );
}

/** Notices slide in, stack behind the newest one and leave on their own. */
export function ToastStack({
  toasts,
  onDismiss,
  duration = 4000,
  max = 3,
  contained = false,
  className = '',
}: ToastStackProps) {
  const visible = toasts.slice(-max);
  return (
    <ol
      className={`mg-toasts ${className}`}
      data-contained={contained}
      aria-label='Notifications'
    >
      {visible.map((toast, index) => (
        <ToastItem
          key={toast.id}
          toast={toast}
          depth={visible.length - 1 - index}
          duration={duration}
          onDismiss={onDismiss}
        />
      ))}
    </ol>
  );
}

.mg-toasts {
  position: fixed;
  right: 16px;
  bottom: 16px;
  z-index: 60;
  width: min(300px, calc(100% - 32px));
  margin: 0;
  padding: 0;
  list-style: none;
}

.mg-toasts[data-contained='true'] {
  position: absolute;
  right: 12px;
  bottom: 12px;
  width: min(280px, calc(100% - 24px));
}

/* Older toasts sit behind the newest: pushed up and scaled down by depth. */
.mg-toasts__slot {
  position: absolute;
  right: 0;
  bottom: 0;
  left: 0;
  opacity: calc(1 - var(--mg-depth) * 0.25);
  transform: translateY(calc(var(--mg-depth) * -10px))
    scale(calc(1 - var(--mg-depth) * 0.05));
  transform-origin: bottom center;
  transition:
    transform 300ms cubic-bezier(0.2, 0.8, 0.2, 1),
    opacity 300ms ease;
}

.mg-toasts__toast {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  padding: 6px 6px 6px 14px;
  border-radius: 12px;
  background: var(--mg-raised, #262626);
  box-shadow: 0 12px 28px -12px rgba(0, 0, 0, 0.6);
  color: #fff;
  animation: mg-toast-in 320ms cubic-bezier(0.2, 0.8, 0.2, 1) both;
}

.mg-toasts__toast[data-leaving='true'] {
  animation: mg-toast-out 240ms ease-in forwards;
}

.mg-toasts__close {
  flex: none;
  width: 44px;
  height: 44px;
  border: 0;
  border-radius: 8px;
  background: none;
  color: inherit;
  font-size: 22px;
  line-height: 1;
  cursor: pointer;
}

.mg-toasts__close:hover {
  background: rgba(255, 255, 255, 0.12);
}

.mg-toasts__close:focus-visible {
  outline: 2px solid var(--mg-accent-text, #648aff);
  outline-offset: -2px;
}

@keyframes mg-toast-in {
  from {
    opacity: 0;
    transform: translateY(24px);
  }
}

@keyframes mg-toast-out {
  to {
    opacity: 0;
    transform: translateX(40px);
  }
}

@keyframes mg-toast-fade-in {
  from {
    opacity: 0;
  }
}

@keyframes mg-toast-fade-out {
  to {
    opacity: 0;
  }
}

@media (prefers-reduced-motion: reduce) {
  .mg-toasts__slot {
    transition: none;
  }
  .mg-toasts__toast {
    animation: mg-toast-fade-in 160ms linear both;
  }
  .mg-toasts__toast[data-leaving='true'] {
    animation: mg-toast-fade-out 160ms linear forwards;
  }
}
